    ('250107','UCAYALI',0,2,1.0483,0.6401,'COMERCIAL'), ('250201','UCAYALI',0,1,1.3305,2.0519,'AGRICOLA'), ('250202','UCAYALI',0,1,1.2126,1.7860,'AGRO_PLURAL'), ('250203','UCAYALI',0,2,1.5611,2.6739,'AGRICOLA'), ('250204','UCAYALI',0,1,1.1980,2.1539,'AGRICOLA'), ('250301','UCAYALI',0,1,1.2961,1.7682,'AGRO_PLURAL'),
    ('250302','UCAYALI',0,1,1.5343,2.4785,'AGRICOLA'), ('250303','UCAYALI',0,2,1.5831,2.5798,'AGRICOLA'), ('250304','UCAYALI',0,2,1.5279,2.3018,'AGRICOLA'), ('250305','UCAYALI',0,1,1.3421,1.8775,'AGRO_PLURAL'), ('250306','UCAYALI',0,0,1.4867,2.2602,'AGRICOLA'), ('250307','UCAYALI',0,0,1.4867,2.2602,'AGRICOLA'),
    ('250401','UCAYALI',0,1,1.0384,1.6539,'AGRO_PLURAL')
)

, zona AS (
    SELECT d.ubigeo_reniec,
           CASE WHEN f.r >= 4 THEN 'R45' WHEN f.r = 3 THEN 'R3'
                WHEN f.r >= 1 THEN 'R12' ELSE 'R0' END AS z
    FROM fen f
    JOIN e_perm_aws.t_mst_ubigeos_rsk d ON f.ubigeo = d.ubigeo_sunat
)
, geo AS (
    SELECT key_value, max_by(cod_ubi_domicilio, fec_dato) AS ubi_reniec
    FROM e_perm_aws.t_mst_reniec_rsk
    WHERE cod_ubi_domicilio IS NOT NULL AND cod_ubi_domicilio <> ''
    GROUP BY key_value
)
, po AS (
    SELECT CAST(codmes AS INTEGER) AS codmes, id_value, flg_target_pp_12m AS y
    FROM disc_model_owner.pp_vc_ds_po_origpp
    WHERE flg_calib_rd = 1
      AND CAST(codmes AS INTEGER) BETWEEN 201901 AND 202504
      AND subproducto_ = '5.P FACIL'
      AND cod_instit_financiera = '00002'
)

SELECT CAST(p.codmes/100 AS INTEGER) AS anio,
       count(*)                                              AS n_po,
       count(g.key_value)                                    AS n_con_reniec,
       count(z.ubigeo_reniec)                                AS n_con_zona,
       round(100.0*count(z.ubigeo_reniec)/count(*), 2)       AS pct_cobertura
FROM po p
LEFT JOIN geo  g ON p.id_value    = g.key_value
LEFT JOIN zona z ON g.ubi_reniec  = z.ubigeo_reniec
GROUP BY 1 ORDER BY 1
